-- Every row should have difference = 0.00
SELECT
    o.id,
    o.total_amount,
    SUM(oi.item_price_snapshot * oi.quantity) AS calculated_total,
    o.total_amount - SUM(oi.item_price_snapshot * oi.quantity) AS difference
FROM orders o
JOIN order_items oi ON oi.order_id = o.id
GROUP BY o.id, o.total_amount
ORDER BY o.created_at;